#!/usr/bin/env python3
"""
Test‑suite für engine.py gemäß der Spezifikation.

- prüft generate, solutions, conflicts und CLUES
- führt `python engine.py neu <stufe>` aus und validiert die JSON‑Ausgabe
- erzeugt pro Schwierigkeitsgrad (leicht, mittel, schwer) 10 Rätsel
- bei erstem Fehler wird mit exit‑Code 1 abgebrochen
"""

import sys
import json
import subprocess
import time
from pathlib import Path

# ------------------------------------------------------------
# Hilfsfunktionen
# ------------------------------------------------------------
def abort(msg: str) -> None:
    """Gibt Fehlermeldung aus und beendet das Programm mit Code 1."""
    print(f"FEHLER: {msg}")
    sys.exit(1)


def ok(msg: str) -> None:
    """Gibt Bestätigung aus."""
    print(f"OK: {msg}")


def load_engine():
    """Importiert das zu testende Modul."""
    try:
        import engine
    except Exception as e:
        abort(f"engine.py lässt sich nicht importieren: {e}")
    return engine


def run_cli(level: str):
    """Startet `python engine.py neu <level>` und gibt das geladene JSON zurück."""
    cmd = [sys.executable, "engine.py", "neu", level]
    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, check=True, timeout=5
        )
    except subprocess.CalledProcessError as e:
        abort(f"CLI‑Aufruf fehlgeschlagen ({' '.join(cmd)}): {e.stderr.strip()}")
    except subprocess.TimeoutExpired:
        abort(f"CLI‑Aufruf timed out ({' '.join(cmd)})")
    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError as e:
        abort(f"CLI‑Ausgabe ist kein gültiges JSON: {e}")
    return data


def check_clues_count(puzzle: list[int], level: str, clues_dict: dict):
    """Prüft, ob die Anzahl der vorgegebenen Zahlen dem CLUES‑Wert entspricht."""
    expected = clues_dict.get(level)
    if expected is None:
        abort(f"Unbekannte Stufe '{level}' in CLUES")
    actual = sum(1 for v in puzzle if v != 0)
    if actual != expected:
        abort(
            f"Clues‑Zählung stimmt nicht für Stufe '{level}': erwartet {expected}, got {actual}"
        )


def check_unique_solution(engine_mod, puzzle):
    """Verifiziert, dass genau eine Lösung existiert."""
    sols = engine_mod.solutions(puzzle, limit=2)
    if not isinstance(sols, list):
        abort("solutions() liefert kein list")
    if len(sols) != 1:
        abort(f"Puzzle hat {len(sols)} Lösungen, erwartet genau 1")
    # optional: Konsistenz mit gelieferter Lösung prüfen
    sol = sols[0]
    if any(not (0 <= v <= 9) for v in sol) or len(sol) != 81:
        abort("Ungültige Lösung zurückgegeben")


def check_conflicts_self(engine_mod):
    """Testet conflicts() an fest definierten Gittern."""
    # 1. Leeres Gitter → keine Konflikte
    empty = [0] * 81
    if engine_mod.conflicts(empty):
        abort("conflicts() meldet Konflikte in einem leeren Gitter")

    # 2. Vollständig korrektes Sudoku (bekanntes Muster) → keine Konflikte
    solved = [
        5, 3, 4, 6, 7, 8, 9, 1, 2,
        6, 7, 2, 1, 9, 5, 3, 4, 8,
        1, 9, 8, 3, 4, 2, 5, 6, 7,
        8, 5, 9, 7, 6, 1, 4, 2, 3,
        4, 2, 6, 8, 5, 3, 7, 9, 1,
        7, 1, 3, 9, 2, 4, 8, 5, 6,
        9, 6, 1, 5, 3, 7, 2, 8, 4,
        2, 8, 7, 4, 1, 9, 6, 3, 5,
        3, 4, 5, 2, 8, 6, 1, 7, 9,
    ]
    if engine_mod.conflicts(solved):
        abort("conflicts() meldet Konflikte in einem korrekten Sudoku")

    # 3. Gitter mit einem doppelten Wert in Zeile 0 (Index 0 und 1 = 5)
    faulty = solved.copy()
    faulty[1] = 5  # nun gibt es ein Duplikat in Zeile 0 (Index 0 und 1)
    conflicted = engine_mod.conflicts(faulty)
    expected = {0, 1}
    if conflicted != expected:
        abort(
            f"conflicts() liefert {conflicted} statt erwarteter {expected} für Zeilen‑Duplikat"
        )

    # 4. Gitter mit einem doppelten Wert in Spalte 0 (Index 0 und 9 = 5)
    faulty = solved.copy()
    faulty[9] = 5
    conflicted = engine_mod.conflicts(faulty)
    expected = {0, 9}
    if conflicted != expected:
        abort(
            f"conflicts() liefert {conflicted} statt erwarteter {expected} für Spalten‑Duplikat"
        )

    # 5. Gitter mit einem doppelten Wert im Block (oben links) (Index 0 und 10 = 5)
    faulty = solved.copy()
    faulty[10] = 5
    conflicted = engine_mod.conflicts(faulty)
    expected = {0, 10}
    if conflicted != expected:
        abort(
            f"conflicts() liefert {conflicted} statt erwarteter {expected} für Block‑Duplikat"
        )


# ------------------------------------------------------------
# Haupttestlogik
# ------------------------------------------------------------
def main():
    engine_mod = load_engine()

    # 1. CLUES vorhanden und korrekt formatiert
    if not hasattr(engine_mod, "CLUES"):
        abort("engine.py definiert kein CLUES")
    if not isinstance(engine_mod.CLUES, dict):
        abort("CLUES ist kein dict")
    ok("CLUES ist definiert und vom Typ dict")

    # 2. Grundlegende API‑Funktionen vorhanden
    for func in ("generate", "solutions", "conflicts"):
        if not hasattr(engine_mod, func):
            abort(f"engine.py fehlt Funktion {func}")
    ok("generate, solutions, conflicts sind vorhanden")

    # 3. Konfliktprüfung an statischen Gittern
    check_conflicts_self(engine_mod)
    ok("conflicts() funktioniert für vordefinierte Gitter")

    # 4. Generation & Einzigartigkeit pro Schwierigkeitsgrad
    levels = ["leicht", "mittel", "schwer"]
    for lvl in levels:
        for i in range(10):
            start = time.time()
            data = engine_mod.generate(lvl)
            if not isinstance(data, dict):
                abort(f"generate({lvl}) gibt kein dict zurück")
            for key in ("puzzle", "solution", "clues", "level"):
                if key not in data:
                    abort(f"generate({lvl}) fehlt Schlüssel {key}")
            if data["level"] != lvl:
                abort(f"generate({lvl}) gibt falsche level‑Angabe zurück")
            puzzle = data["puzzle"]
            solution = data["solution"]
            clues = data["clues"]

            # 4a. Strukturprüfung
            if not (isinstance(puzzle, list) and isinstance(solution, list)):
                abort("puzzle/solution sind keine Listen")
            if len(puzzle) != 81 or len(solution) != 81:
                abort("puzzle/solution haben nicht genau 81 Einträge")

            # 4b. Clues‑Anzahl prüfen
            check_clues_count(puzzle, lvl, engine_mod.CLUES)

            # 4c. Lösung muss das Puzzle korrekt ergänzen
            # (alle vorgegebenen Zahlen müssen mit solution übereinstimmen)
            for idx, val in enumerate(puzzle):
                if val != 0 and val != solution[idx]:
                    abort(
                        f"Puzzle‑Wert an Index {idx} stimmt nicht mit der Lösung überein"
                    )

            # 4d. Eindeutige Lösung prüfen
            check_unique_solution(engine_mod, puzzle)

            # 4e. Performance (optional, nicht zwingend, aber laut Spec)
            duration = time.time() - start
            if duration > 0.2:
                abort(
                    f"generate({lvl}) dauerte {duration:.3f}s (>200 ms) – Performance‑Kriterium verletzt"
                )
        ok(f"generate, uniqueness & clues für Stufe '{lvl}' (10×) OK")

    # 5. CLI‑Aufruf prüfen
    for lvl in levels:
        data = run_cli(lvl)

        # gleiche Prüfungen wie bei generate
        for key in ("puzzle", "solution", "clues", "level"):
            if key not in data:
                abort(f"CLI‑Ausgabe für {lvl} fehlt Schlüssel {key}")

        if data["level"] != lvl:
            abort(f"CLI‑Ausgabe level‑Feld falsch ({data['level']} statt {lvl})")

        puzzle = data["puzzle"]
        solution = data["solution"]
        clues = data["clues"]

        if not (isinstance(puzzle, list) and isinstance(solution, list)):
            abort("CLI‑Ausgabe: puzzle/solution sind keine Listen")
        if len(puzzle) != 81 or len(solution) != 81:
            abort("CLI‑Ausgabe: puzzle/solution nicht 81 lang")

        check_clues_count(puzzle, lvl, engine_mod.CLUES)

        # Lösungskonsistenz prüfen
        for idx, val in enumerate(puzzle):
            if val != 0 and val != solution[idx]:
                abort(
                    f"CLI‑Puzzle‑Wert an Index {idx} stimmt nicht mit der Lösung überein"
                )

        # Eindeutige Lösung
        check_unique_solution(engine_mod, puzzle)

    ok("CLI‑Aufruf `python engine.py neu <stufe>` funktioniert für alle Stufen")

    # --------------------------------------------------------
    # Abschluss
    # --------------------------------------------------------
    ok("Alle Tests erfolgreich bestanden")
    sys.exit(0)


if __name__ == "__main__":
    main()
